package android.content.pm;
import android.content.*;
import org.padtv.bridge.*;
import org.w3c.dom.*;
import java.util.*;
/** Only this package is visible inside the application's sandbox. */
public class PackageManager {
    public static final int GET_ACTIVITIES=1,GET_PERMISSIONS=4096,MATCH_DEFAULT_ONLY=65536,PERMISSION_GRANTED=0,PERMISSION_DENIED=-1;
    public static class NameNotFoundException extends Exception {public NameNotFoundException(String s){super(s);}}
    private static void own(String p)throws NameNotFoundException{if(!Host.packageName.equals(p))throw new NameNotFoundException(p);}
    public ApplicationInfo getApplicationInfo(String p,int flags)throws NameNotFoundException{own(p);ApplicationInfo i=new ApplicationInfo();i.packageName=p;i.sourceDir="/app/original.apk";i.publicSourceDir=i.sourceDir;i.dataDir="/data";Element app=(Element)Manifest.get().getElementsByTagName("application").item(0);i.className=app.hasAttribute("name")?Manifest.className(app.getAttribute("name")):null;i.name=i.className;return i;}
    public CharSequence getApplicationLabel(ApplicationInfo info){Element app=(Element)Manifest.get().getElementsByTagName("application").item(0);String label=app.getAttribute("label");if(label.startsWith("@0x"))return new android.content.res.Resources().getString((int)Long.parseLong(label.substring(3),16));return label.isEmpty()?info.packageName:label;}
    public PackageInfo getPackageInfo(String p,int flags)throws NameNotFoundException{own(p);PackageInfo i=new PackageInfo();i.packageName=p;i.applicationInfo=getApplicationInfo(p,0);Element root=Manifest.get().getDocumentElement();i.versionName=root.getAttribute("versionName");i.versionCode=Integer.parseInt(root.getAttribute("versionCode"));NodeList a=Manifest.get().getElementsByTagName("activity");i.activities=new ActivityInfo[a.getLength()];for(int n=0;n<a.getLength();n++){ActivityInfo x=new ActivityInfo();Element e=(Element)a.item(n);x.name=Manifest.className(e.getAttribute("name"));x.packageName=p;x.applicationInfo=i.applicationInfo;x.exported=Boolean.parseBoolean(e.getAttribute("exported"));i.activities[n]=x;}NodeList permissions=Manifest.get().getElementsByTagName("uses-permission");i.requestedPermissions=new String[permissions.getLength()];for(int n=0;n<permissions.getLength();n++)i.requestedPermissions[n]=((Element)permissions.item(n)).getAttribute("name");return i;}
    public List<ApplicationInfo> getInstalledApplications(int flags){try{return Collections.singletonList(getApplicationInfo(Host.packageName,flags));}catch(NameNotFoundException impossible){throw new AssertionError(impossible);}}
    public Intent getLaunchIntentForPackage(String p){return launch(p,Intent.CATEGORY_LAUNCHER);}public Intent getLeanbackLaunchIntentForPackage(String p){return launch(p,Intent.CATEGORY_LEANBACK_LAUNCHER);}
    private Intent launch(String p,String category){if(!Host.packageName.equals(p))return null;NodeList nodes=Manifest.get().getElementsByTagName("activity");for(int n=0;n<nodes.getLength();n++){Element a=(Element)nodes.item(n);NodeList filters=a.getElementsByTagName("intent-filter");for(int j=0;j<filters.getLength();j++){Element f=(Element)filters.item(j);boolean main=false,cat=false;NodeList actions=f.getElementsByTagName("action");for(int k=0;k<actions.getLength();k++)main|=Intent.ACTION_MAIN.equals(((Element)actions.item(k)).getAttribute("name"));NodeList cats=f.getElementsByTagName("category");for(int k=0;k<cats.getLength();k++)cat|=category.equals(((Element)cats.item(k)).getAttribute("name"));if(main&&cat)return new Intent(Intent.ACTION_MAIN).addCategory(category).setClassName(p,Manifest.className(a.getAttribute("name")));}}return null;}
}
